/* Standardkategorien: Emoji → Linien-Icon. Nur Anzeige: gespeichert bleibt das Emoji.
   Gilt nur, solange die Kategorie noch ihr Standard-Emoji trägt (ändert der Nutzer das Symbol, gilt seine Wahl). */
const CATD = {
  wohnen: ['🏠', 'house'],
  lebensmittel: ['🛒', 'cart'],
  mobil: ['🚗', 'car-front'],
  freizeit: ['🎉', 'balloon'],
  gesund: ['💊', 'capsule'],
  kleidung: ['👕', 'handbag'],
  abos: ['🔁', 'arrow-repeat'],
  sonst_e: ['📦', 'box-seam'],
  gehalt: ['💼', 'briefcase'],
  neben: ['💸', 'cash-coin'],
  geschenk: ['🎁', 'gift'],
  sonst_i: ['✨', 'stars'],
};
/* SVG eines Symbols (leer, wenn unbekannt) */
const svgi = (n) =>
  CATI[n]
    ? `<svg class="bi cic" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" focusable="false">${CATI[n]}</svg>`
    : '';
/* Symbolname einer Kategorie (c = { id, i }): 'bi:<name>' direkt, Standardkategorie mit Standard-Emoji über CATD, sonst '' (= Emoji) */
const cin = (c) => {
  const i = String((c && c.i) || '');
  if (i.startsWith('bi:')) return CATI[i.slice(3)] ? i.slice(3) : 'tag';
  const d = c && CATD[c.id];
  return d && d[0] == i ? d[1] : '';
};
/* Anzeige eines Kategorie-Symbols als HTML: Linien-Icon oder Emoji */
const ci = (c) => {
  const n = cin(c);
  return n ? svgi(n) : esc((c && c.i) || '');
};
/* Nur-Text-Variante (für <option>): Emoji oder leer */
const cit = (c) => (cin(c) ? '' : String((c && c.i) || ''));
